import React, { useEffect, useState } from "react";
import "./ViewProducts.css";

const ViewProducts = () => {
  const [products, setProducts] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const productsPerPage = 6;

  const fetchProducts = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/products");
      const data = await res.json();
      setProducts(data);
    } catch (err) {
      console.error("Error fetching products", err);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const deleteProduct = async (productId) => {
    if (!window.confirm("Are you sure you want to delete this product?")) return;

    try {
      const res = await fetch(`http://localhost:5000/api/products/${productId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("adminToken")}`,
        },
      });

      if (!res.ok) throw new Error("Failed to delete product");
      setProducts(products.filter((p) => p.id !== productId));
    } catch (err) {
      console.error("Delete error:", err);
      alert("Failed to delete product");
    }
  };

  // Pagination logic
  const indexOfLast = currentPage * productsPerPage;
  const indexOfFirst = indexOfLast - productsPerPage;
  const currentProducts = products.slice(indexOfFirst, indexOfLast);
  const totalPages = Math.ceil(products.length / productsPerPage);

  return (
    <div className="product-grid">
      {currentProducts.map((product) => (
        <div key={product.id} className="product-card">
          <img
            src={`http://localhost:5000/${product.image_path}`}
            alt={product.name}
            className="product-image"
          />
          <div className="product-name">{product.name}</div>
          <div className="product-details">₦{product.price}</div>
          <div className="product-details">Stock: {product.stock}</div>
          <div className="action-buttons">
            <button className="btn-edit" onClick={() => alert("Edit feature coming soon!")}>
              Edit
            </button>
            <button className="btn-delete" onClick={() => deleteProduct(product.id)}>
              Delete
            </button>
          </div>
        </div>
      ))}

      {/* Pagination Controls */}
      <div style={{ marginTop: "1rem", textAlign: "center" }}>
        {Array.from({ length: totalPages }, (_, i) => i + 1).map((pageNum) => (
          <button
            key={pageNum}
            onClick={() => setCurrentPage(pageNum)}
            style={{
              margin: "0 5px",
              padding: "8px 12px",
              borderRadius: "5px",
              background: currentPage === pageNum ? "#007bff" : "#eee",
              color: currentPage === pageNum ? "white" : "#333",
              border: "none",
              cursor: "pointer",
            }}
          >
            {pageNum}
          </button>
        ))}
      </div>
    </div>
  );
};

export default ViewProducts;
